function exampleLine(value: string) {
  const line = value.split(/\r?\n/u).find((item) => item.trim())?.trim() ?? "—";
  return line.length > 120 ? `${line.slice(0, 117)}…` : line;
}

function inputGuide(value: string, t: (typeof ui)[Locale]) {
  const trimmed = value.trim();
  const first = exampleLine(value);
  const samples = value.split(/\r?\n/u).map((line) => line.trim()).filter(Boolean).slice(0, 8);
  let json = false;
  if (/^[\[{]/u.test(trimmed)) try { JSON.parse(trimmed); json = true; } catch { json = false; }
  if (json) return { text: t.jsonGuide, kind: "JSON", example: first };
  if (samples.length && samples.every((line) => line.includes("=>") && line.split("=>").every((part) => part.trim()))) return { text: t.arrowGuide, kind: "input => output", example: first };
  if (samples.some((line) => /^\[[^\]]+\]$/u.test(line)) && samples.every((line) => /^\[[^\]]+\]$/u.test(line) || /^[^=\s][^=]*=/.test(line))) return { text: t.iniGuide, kind: "INI", example: first };
  if (samples.length && samples.every((line) => /^[^=\s][^=]*=/.test(line))) return { text: t.pairGuide, kind: "key=value", example: samples.map((line) => line.slice(0, line.indexOf("=")).trim()).join(" · ") };
  if (first.includes("|")) return { text: t.pipeGuide, kind: `${first.split("|").length} fields`, example: first };
  if (/^[\d\s,;.+-]+$/u.test(trimmed) && /\d/u.test(trimmed)) return { text: t.numberGuide, kind: "numbers", example: first };
  if (/[,;\t]/u.test(first) && samples.length > 1) return { text: t.csvGuide, kind: "CSV", example: first };
  if (samples.length > 1) return { text: t.lineGuide, kind: "lines", example: first };
  return { text: t.textGuide, kind: "text", example: first };
}

